"use strict";
// Plain JavaScript; @types/tallyjs describes it, except that an empty
// list has no max (undefined) and no mean (null).
function totals(values) {
  var sum = 0;
  for (var i = 0; i < values.length; i++) sum += values[i];
  var max = values.length === 0 ? undefined : Math.max.apply(null, values);
  var mean = values.length === 0 ? null : sum / values.length;
  return { count: values.length, sum: sum, max: max, mean: mean };
}
exports.totals = totals;
